STANDARD = {'browserName', 'browserVersion', 'platformName', 'acceptInsecureCerts', 'pageLoadStrategy', 'proxy',
            'setWindowRect', 'timeouts', 'strictFileInteractability', 'unhandledPromptBehavior', 'webSocketUrl'}

def problems(caps):
    out = []
    if 'platformName' not in caps:
        out.append('missing platformName')
    if 'appium:automationName' not in caps:
        out.append('missing appium:automationName')
    for key in caps:
        if key not in STANDARD and ':' not in key:
            out.append(f'unprefixed {key}')
    if not any(k in caps for k in ('appium:app', 'appium:appPackage', 'appium:bundleId', 'browserName')):
        out.append('no app or browser')
    return sorted(out)
